module Prob_6_35c (output [3: 0] A, input [3:0] I, input Shift, Load,  Clock);  Register_Cell R0 (A[0], I[0], A[1], Shift, Load, Clock);  Register_Cell R1 (A[1], I[1], A[2], Shift, Load, Clock);  Register_Cell R2 (A[2], I[2], A[3], Shift, Load, Clock);  Register_Cell R3 (A[3], I[3], A[0], Shift, Load, Clock);endmodule module Register_Cell (output A, input I, Serial_in, Shift, Load, Clock);  DFF M0 (A, D, Clock);  not (Shift_b, Shift);  not (Load_b, Load);  and (w1, Shift, Serial_in);  and (w2, Shift_b, Load, I);  and (w3, A, Shift_b, Load_b);  or (D, w1, w2, w3);endmodule